
INSERT INTO reviews (product_id, user_id, rating, title, comment, is_approved) VALUES
-- iPhone 15 Pro Max
('12c4ebe4-f65d-4e6d-8fbe-f757c98f0e7d', '42a19bc3-1f3b-46cf-9cbb-20bab61a5805', 5, 'Best iPhone ever!', 'The titanium design feels incredible. Camera is absolutely stunning, especially the 5x zoom. Battery lasts all day easily.', true),
('12c4ebe4-f65d-4e6d-8fbe-f757c98f0e7d', '42a19bc3-1f3b-46cf-9cbb-20bab61a5805', 4, 'Great but pricey', 'Amazing phone with top-notch performance. Only downside is the high price tag, but you get what you pay for.', true),
-- Samsung Galaxy S24 Ultra
('e1bd61e0-a91f-4f08-9529-59fa375c94cc', '42a19bc3-1f3b-46cf-9cbb-20bab61a5805', 5, 'Galaxy AI is a game changer', 'The AI features are incredibly useful. Circle to Search, live translate, and the 200MP camera takes breathtaking photos.', true),
('e1bd61e0-a91f-4f08-9529-59fa375c94cc', '42a19bc3-1f3b-46cf-9cbb-20bab61a5805', 4, 'S Pen is underrated', 'Love using the S Pen for quick notes. Display is gorgeous and battery easily lasts a full day with heavy use.', true),
-- MacBook Pro 16
('c504d219-268f-4f79-ad18-ec93333a306f', '42a19bc3-1f3b-46cf-9cbb-20bab61a5805', 5, 'Absolute powerhouse', 'Handles 4K video editing and 3D rendering without breaking a sweat. The M3 Max chip is insanely fast. Best laptop I have ever owned.', true),
('c504d219-268f-4f79-ad18-ec93333a306f', '42a19bc3-1f3b-46cf-9cbb-20bab61a5805', 5, 'Worth every penny', 'Battery life is phenomenal for a 16-inch laptop. The display is the best in any laptop, period.', true),
-- Sony WH-1000XM5
('47ce6382-f84c-4b5f-838d-d366f8e17b0a', '42a19bc3-1f3b-46cf-9cbb-20bab61a5805', 5, 'Silence is golden', 'Noise cancellation is on another level. I wear these 8 hours a day for work and they are incredibly comfortable.', true),
